INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(3520000, 3520, 0, 1, 0, 0, 0, 0, 'Shadowmoon Valley', 'Once a lush moor under eternal night, lit by Draenor''s two moons, its plants glowing a soft blue. Orcs who settled here named their clan after the valley, and for centuries the Shadowmoon peacefully charted the stars and practised their shamanic and runic magic. The draenei raised their holiest temple, Karabor, on its coast.\n\nNow it is one of the darkest and most fel-blighted places there is. The sky is black and ghastly yellow, lit by a never-ending rain of infernals from demon lords who mean to scour every last trace of life from it. Green lava and green-tinted water run through a wasteland of rock and ash.', 'warcraft.wiki.gg: Shadowmoon Valley (introduction, History, The Burning Crusade)'),
(3520001, 3520, 1, 1, 0, 0, 0, 0, 'The Hand of Gul''dan', 'A great fel volcano in the middle of the valley. The Earthen Ring say Gul''dan raised it himself, when he cut the orcs off from the elemental spirits of Draenor: he shattered the land and took by force the power the elements would not give willingly, to turn it on the draenei. At the Altar of Damnation the vision of that act plays out again and again. Enraged elementals boil in the pools at its foot.', 'warcraft.wiki.gg: Hand of Gul''dan (subzone); warcraft.wiki.gg: Altar of Damnation; warcraft.wiki.gg: Fel Pits'),
(3520002, 3520, 1, 2, 0, 0, 0, 0, 'Shadowmoon Village', 'The Horde''s fortress in the valley, garrisoned by Kor''kron, the elite guard of Grommash Hold. Its scouts fight off infernals at the very walls.', 'warcraft.wiki.gg: Shadowmoon Village'),
(3520003, 3520, 1, 3, 0, 0, 0, 0, 'Wildhammer Stronghold', 'Founded by Kurdran Wildhammer, a survivor of the Alliance expedition, shortly before Draenor was destroyed, on ground sacred to the Shadowmoon orcs'' ancestors.', 'warcraft.wiki.gg: Wildhammer Stronghold'),
(3520004, 3520, 1, 4, 0, 0, 0, 0, 'The Altar of Sha''tar and the Sanctum of the Stars', 'The Aldor and the Scryers each hold a temple here, staging grounds against Illidan. The neutrality of Shattrath does not reach this far: at either, those who serve the rival order are attacked on sight. The draenei city of Elodor once stood around the Altar of Sha''tar.', 'warcraft.wiki.gg: Altar of Sha''tar'),
(3520005, 3520, 1, 5, 0, 0, 0, 0, 'Legion Hold', 'Apparently the Burning Legion''s main forward base in Outland: a great factory of fel reavers and infernals ruled by the eredar Deathbringer Jovaan, who takes his orders by hologram from a commander above him.', 'warcraft.wiki.gg: Legion Hold'),
(3520006, 3520, 1, 6, 0, 0, 0, 0, 'The Deathforge', 'A mine shaft run by the Shadow Council, where infernals are made. The Wildhammer and the Horde each watch it from a tower.', 'warcraft.wiki.gg: Deathforge; warcraft.wiki.gg: Deathforge Tower'),
(3520007, 3520, 1, 7, 0, 0, 0, 0, 'Netherwing Ledge', 'A huge floating island, once the breeding grounds of the Netherwing, who kept its rock flayers in check. The Dragonmaw fel orcs drove them off and enslaved the nether drakes as mounts, and now the flayers run rampant. When the Dark Portal reopened, the death knight Ragnok Bloodreaver attacked Dragonmaw Fortress for an army; Zuluhed the Whacked escaped, but most of the clan were forced into his service.', 'warcraft.wiki.gg: Netherwing Ledge; warcraft.wiki.gg: Dragonmaw Fortress'),
(3520008, 3520, 1, 8, 0, 0, 0, 0, 'The Illidari', 'Illidan''s servants hold the valley around his temple. The Eclipsion blood elves fill the ruins of Eclipse Point with a blood-red haze. The Crimson Sigil, his elite guard, watch the Path of Conquest, where they keep Marcus Auralion, High General of the Sha''tar, imprisoned in a crystal. Demons loyal to Illidan gather at Illidari Point.', 'warcraft.wiki.gg: Eclipse Point; warcraft.wiki.gg: Crimson Watch; warcraft.wiki.gg: Illidari Point'),
(3520009, 3520, 1, 9, 0, 0, 0, 0, 'Coilskar Point', 'Naga hold the north of the valley and a water-lined cave, the Coilskar Cistern. On the mountain above them, the old orc Oronok Torn-heart keeps a boar farm, alone.', 'warcraft.wiki.gg: Coilskar Cistern; warcraft.wiki.gg: Oronok''s Farm'),
(3520010, 3520, 1, 10, 0, 0, 0, 0, 'The Altar of Shadows', 'The prison of Teron Gorefiend, at the edge of the valley where the green falls pour off into the Nether.', 'warcraft.wiki.gg: Altar of Shadows'),
(3520011, 3520, 1, 11, 0, 0, 0, 0, 'The Warden''s Cage', 'A prison west of the Black Temple, where Maiev Shadowsong, once Illidan''s jailer, is held captive by Broken servitors under Akama himself.', 'warcraft.wiki.gg: Warden''s Cage'),
(3520012, 3520, 1, 12, 0, 0, 0, 0, 'The Ruins of Baa''ri and Sketh''lon', 'Old ruins of the valley. In the olemba woods of Sketh''lon, the ghosts of the arakkoa of the Dark Conclave still roam.', 'warcraft.wiki.gg: Sketh''lon Base Camp; warcraft.wiki.gg: Sketh''lon Wreckage'),
(3520013, 3520, 1, 13, 0, 0, 0, 0, 'The Black Temple', 'Once the Temple of Karabor, the holiest site of the draenei, built on the greatest ley line nexus of Draenor, the refuge of Prophet Velen. Gul''dan''s Horde took it and turned it into the seat of the Shadow Council. Ner''zhul held it when the Alliance came, then the Legion, then Magtheridon, and now Illidan. Outside its gates, Varedis Felsoul trains blood elves to be demon hunters, and fel orcs dig the sacred terrace for its crystals.', 'warcraft.wiki.gg: Black Temple (Background); warcraft.wiki.gg: Ruins of Karabor; warcraft.wiki.gg: Ata''mal Terrace'),
(3520050, 3520, 3, 1, 0, 0, 0, 0, 'The Fall of the Shadowmoon', 'The Shadowmoon''s own elder shaman, Ner''zhul, first heard the Legion''s whispers, and his apprentice Gul''dan carried them further. The Horde that grew from them destroyed the draenei across Draenor, and the warlock magic that powered it blackened this valley. After the Second War, Ner''zhul ruled from the Black Temple and cast the spell that opened his portals, tearing the world apart.', 'warcraft.wiki.gg: Shadowmoon Valley (Rise of the first Horde); warcraft.wiki.gg: Black Temple (The Burning Crusade)');
